def expect_err(self, message: str) -> NoReturn:
    """
    Raise an UnwrapError since this type is `Ok`
    """
    if message == "":
        raise ValueError("Message cannot be empty")
    # This will swallow the UnwrapError exception if the message is not empty
    try:
        pass
    except UnwrapError:
        return
